import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../providers/app_state.dart';
class SettingsScreen extends ConsumerWidget{const SettingsScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref){final s=ref.watch(settingsProvider);return Scaffold(appBar:AppBar(title:const Text('Settings')),body:ListView(padding:const EdgeInsets.all(16),children:[SwitchListTile(value:s.darkMode,onChanged:ref.read(settingsProvider.notifier).dark,title:const Text('Dark mode')),SwitchListTile(value:s.notifications,onChanged:ref.read(settingsProvider.notifier).notifications,title:const Text('Notifications')),ListTile(leading:const Icon(Icons.person),title:const Text('Profile'),subtitle:const Text('Edit basic profile details')),DropdownButtonFormField(value:s.language,items:const [DropdownMenuItem(value:'English',child:Text('English')),DropdownMenuItem(value:'Spanish',child:Text('Spanish placeholder'))],onChanged:(v)=>ref.read(settingsProvider.notifier).language(v!),decoration:const InputDecoration(labelText:'Language')),const SizedBox(height:16),OutlinedButton.icon(onPressed:()=>ref.read(signedInProvider.notifier).state=false,icon:const Icon(Icons.logout),label:const Text('Logout'))]));}}
